    public int findCenter(int[][] edges) {
        int n = edges.length + 1;
        int[] degree = new int[n + 1];
        for (int[] e : edges) {
            degree[e[0]]++;
            degree[e[1]]++;
        }
        for (int i = 1; i <= n; i++) {
            if (degree[i] == edges.length) return i;
        }
        return -1;
    }
