class Solution {
    public int minReorder(int n, int[][] connections) {
        Set<String> set = new HashSet<>();
        List<List<Integer>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] c : connections) {
            set.add(c[0] + "->" + c[1]);
            adj.get(c[0]).add(c[1]);
            adj.get(c[1]).add(c[0]);
        }
        boolean[] vis = new boolean[n];
        return dfs(0, adj, set, vis);
    }
    private int dfs(int u, List<List<Integer>> adj, Set<String> set, boolean[] vis) {
        vis[u] = true;
        int count = 0;
        for (int v : adj.get(u)) {
            if (!vis[v]) {
                if (set.contains(u + "->" + v)) count++;
                count += dfs(v, adj, set, vis);
            }
        }
        return count;
    }
}

