class Solution {
    static class Edge {
        int to, cost;
        Edge(int to, int cost) { this.to = to; this.cost = cost; }
    }
    public int minReorder(int n, int[][] connections) {
        List<List<Edge>> adj = new ArrayList<>();
        for (int i = 0; i < n; i++) adj.add(new ArrayList<>());
        for (int[] c : connections) {
            adj.get(c[0]).add(new Edge(c[1], 1));
            adj.get(c[1]).add(new Edge(c[0], 0));
        }
        return dfs(0, -1, adj);
    }
    private int dfs(int node, int parent, List<List<Edge>> adj) {
        int count = 0;
        for (Edge e : adj.get(node)) {
            if (e.to != parent) {
                count += e.cost + dfs(e.to, node, adj);
            }
        }
        return count;
    }
}

