class Solution {
    public boolean canReach(int[] arr, int start) {
        Queue<Integer> q = new LinkedList<>();
        q.offer(start);
        while (!q.isEmpty()) {
            int cur = q.poll();
            if (arr[cur] == 0) return true;
            if (arr[cur] < 0) continue;
            int step = arr[cur];
            arr[cur] = -arr[cur];
            if (cur + step < arr.length) q.offer(cur + step);
            if (cur - step >= 0) q.offer(cur - step);
        }
        return false;
    }
}

