        }
        return dfs(0, -1, adj, hasApple);
    }
    private int dfs(int u, int p, List<List<Integer>> adj, List<Boolean> hasApple) {
        int total = 0;
        for (int v : adj.get(u)) {
            if (v != p) {
                int cost = dfs(v, u, adj, hasApple);
                if (cost > 0 || hasApple.get(v)) {
                    total += cost + 2;
                }
            }
        }
        return total;
    }
}

