        vis = [[False] * n for _ in range(m)]
        count = 0
        def dfs(r: int, c: int) -> bool:
            if not (0 <= r < m and 0 <= c < n):
                return False
            if grid[r][c] == 1 or vis[r][c]:
                return True
            vis[r][c] = True
            up = dfs(r - 1, c)
            down = dfs(r + 1, c)
            left = dfs(r, c - 1)
            right = dfs(r, c + 1)
            return up and down and left and right
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 0 and not vis[i][j]:
                    if dfs(i, j):
                        count += 1
        return count

